-- Borhan ERP schema. All public refs use un_id (CHAR 36). Money DECIMAL(15,2) in base currency (BDT) unless *_fx.
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, phone VARCHAR(30) UNIQUE, email VARCHAR(150) UNIQUE, password_hash VARCHAR(255) NOT NULL, is_super TINYINT(1) DEFAULT 0, status VARCHAR(20) DEFAULT 'active', lang VARCHAR(5) DEFAULT 'en', last_login_at DATETIME NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, permissions JSON NULL, is_system TINYINT(1) DEFAULT 0, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE user_business_access (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, user_un_id CHAR(36) NOT NULL, business_un_id CHAR(36) NOT NULL, role_un_id CHAR(36) NOT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, UNIQUE KEY uba (user_un_id, business_un_id));
CREATE TABLE refresh_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_un_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, device VARCHAR(120) NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at DATETIME NULL);
CREATE TABLE business_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, modules JSON NULL, icon VARCHAR(40) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE businesses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, business_type_un_id CHAR(36) NULL, base_currency CHAR(3) DEFAULT 'BDT', license_no VARCHAR(60) NULL, phone VARCHAR(30) NULL, address TEXT NULL, logo VARCHAR(255) NULL, status VARCHAR(20) DEFAULT 'active', meta JSON NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_un_id CHAR(36) NULL, `key` VARCHAR(80) NOT NULL, value TEXT NULL, UNIQUE KEY sk (business_un_id, `key`));
CREATE TABLE currencies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, code CHAR(3) NOT NULL UNIQUE, name VARCHAR(60) NOT NULL, symbol VARCHAR(8) NULL, rate DECIMAL(15,6) DEFAULT 1, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE units (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(40) NOT NULL, symbol VARCHAR(12) NOT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE number_sequences (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_un_id CHAR(36) NOT NULL, `key` VARCHAR(30) NOT NULL, prefix VARCHAR(20) NOT NULL, next_no INT UNSIGNED DEFAULT 1, UNIQUE KEY sq (business_un_id, `key`));
CREATE TABLE attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NULL, entity_type VARCHAR(40) NULL, entity_un_id CHAR(36) NULL, path VARCHAR(255) NOT NULL, name VARCHAR(200) NULL, mime VARCHAR(80) NULL, size INT UNSIGNED NULL, created_by CHAR(36) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY ent (entity_type, entity_un_id));
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_un_id CHAR(36) NULL, business_un_id CHAR(36) NULL, action VARCHAR(20) NOT NULL, entity_type VARCHAR(40) NOT NULL, entity_un_id CHAR(36) NULL, `before` JSON NULL, `after` JSON NULL, ip VARCHAR(45) NULL, created_at DATETIME NULL, KEY ent (entity_type, entity_un_id));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, user_un_id CHAR(36) NULL, business_un_id CHAR(36) NULL, type VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, body TEXT NULL, entity_type VARCHAR(40) NULL, entity_un_id CHAR(36) NULL, dedupe_key VARCHAR(120) NULL UNIQUE, read_at DATETIME NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE device_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_un_id CHAR(36) NOT NULL, token VARCHAR(255) NOT NULL UNIQUE, platform VARCHAR(20) NULL, created_at DATETIME NULL);
CREATE TABLE custom_fields (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NULL, entity VARCHAR(40) NOT NULL, scope VARCHAR(60) NULL, `key` VARCHAR(60) NOT NULL, label VARCHAR(120) NOT NULL, type VARCHAR(20) DEFAULT 'text', options JSON NULL, required TINYINT(1) DEFAULT 0, sort INT DEFAULT 0, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NULL, kind VARCHAR(20) NOT NULL, name VARCHAR(120) NOT NULL, parent_un_id CHAR(36) NULL, icon VARCHAR(40) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE parties (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, roles JSON NULL, phone VARCHAR(30) NULL, phone2 VARCHAR(30) NULL, email VARCHAR(150) NULL, nid VARCHAR(40) NULL, passport_no VARCHAR(30) NULL, passport_expiry DATE NULL, dob DATE NULL, address TEXT NULL, photo VARCHAR(255) NULL, company VARCHAR(150) NULL, meta JSON NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY ph (phone), KEY pp (passport_no));
CREATE TABLE accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, code VARCHAR(30) NULL, name VARCHAR(120) NOT NULL, type VARCHAR(20) NOT NULL, subtype VARCHAR(20) NULL, bank_name VARCHAR(100) NULL, account_no VARCHAR(60) NULL, branch VARCHAR(100) NULL, currency CHAR(3) DEFAULT 'BDT', is_system TINYINT(1) DEFAULT 0, status VARCHAR(20) DEFAULT 'active', created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, UNIQUE KEY bc (business_un_id, code));
CREATE TABLE transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, no VARCHAR(30) NULL, date DATE NOT NULL, type VARCHAR(20) NOT NULL, party_un_id CHAR(36) NULL, entity_type VARCHAR(40) NULL, entity_un_id CHAR(36) NULL, currency CHAR(3) DEFAULT 'BDT', rate DECIMAL(15,6) DEFAULT 1, amount DECIMAL(15,2) NOT NULL, ref_no VARCHAR(60) NULL, note TEXT NULL, status VARCHAR(10) DEFAULT 'posted', created_by CHAR(36) NULL, idem_key VARCHAR(64) NULL UNIQUE, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY bd (business_un_id, date), KEY ent (entity_type, entity_un_id));
CREATE TABLE transaction_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transaction_un_id CHAR(36) NOT NULL, business_un_id CHAR(36) NOT NULL, account_un_id CHAR(36) NOT NULL, party_un_id CHAR(36) NULL, category_un_id CHAR(36) NULL, project_un_id CHAR(36) NULL, debit DECIMAL(15,2) DEFAULT 0, credit DECIMAL(15,2) DEFAULT 0, date DATE NOT NULL, status VARCHAR(10) DEFAULT 'posted', KEY acc (account_un_id), KEY pty (party_un_id), KEY tx (transaction_un_id));
CREATE TABLE expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, no VARCHAR(30) NULL, date DATE NOT NULL, title VARCHAR(200) NOT NULL, category_un_id CHAR(36) NULL, amount DECIMAL(15,2) NOT NULL, currency CHAR(3) DEFAULT 'BDT', rate DECIMAL(15,6) DEFAULT 1, account_un_id CHAR(36) NULL, party_un_id CHAR(36) NULL, project_un_id CHAR(36) NULL, visa_file_un_id CHAR(36) NULL, note TEXT NULL, status VARCHAR(12) DEFAULT 'pending', transaction_un_id CHAR(36) NULL, is_recurring TINYINT(1) DEFAULT 0, recur_interval VARCHAR(10) NULL, recur_next_date DATE NULL, recur_end_date DATE NULL, recur_parent_un_id CHAR(36) NULL, created_by CHAR(36) NULL, approved_by CHAR(36) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE visa_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, no VARCHAR(30) NULL, supplier_un_id CHAR(36) NULL, country VARCHAR(60) NOT NULL, sponsor VARCHAR(150) NULL, job_title VARCHAR(120) NULL, quantity INT UNSIGNED NOT NULL, unit_cost DECIMAL(15,2) NOT NULL, currency CHAR(3) DEFAULT 'BDT', rate DECIMAL(15,6) DEFAULT 1, purchase_date DATE NULL, expiry_date DATE NULL, status VARCHAR(20) DEFAULT 'active', transaction_un_id CHAR(36) NULL, meta JSON NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE pipelines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, name VARCHAR(100) NOT NULL, country VARCHAR(60) NULL, strict TINYINT(1) DEFAULT 0, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE pipeline_stages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, pipeline_un_id CHAR(36) NOT NULL, name VARCHAR(100) NOT NULL, sort INT DEFAULT 0, color VARCHAR(9) NULL, sla_days INT NULL, required_docs JSON NULL, is_terminal TINYINT(1) DEFAULT 0, triggers_commission TINYINT(1) DEFAULT 0, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE visa_files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, no VARCHAR(30) NULL, candidate_un_id CHAR(36) NOT NULL, batch_un_id CHAR(36) NULL, pipeline_un_id CHAR(36) NULL, stage_un_id CHAR(36) NULL, stage_changed_at DATETIME NULL, country VARCHAR(60) NULL, job_title VARCHAR(120) NULL, sponsor VARCHAR(150) NULL, visa_no VARCHAR(60) NULL, work_permit_no VARCHAR(60) NULL, visa_expiry DATE NULL, sub_agent_un_id CHAR(36) NULL, commission_type VARCHAR(10) DEFAULT 'fixed', commission_value DECIMAL(15,2) DEFAULT 0, commission_accrued TINYINT(1) DEFAULT 0, purchase_cost DECIMAL(15,2) DEFAULT 0, selling_price DECIMAL(15,2) DEFAULT 0, discount DECIMAL(15,2) DEFAULT 0, currency CHAR(3) DEFAULT 'BDT', rate DECIMAL(15,6) DEFAULT 1, status VARCHAR(20) DEFAULT 'active', note TEXT NULL, meta JSON NULL, created_by CHAR(36) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY st (stage_un_id));
CREATE TABLE visa_stage_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, visa_file_un_id CHAR(36) NOT NULL, from_stage_un_id CHAR(36) NULL, to_stage_un_id CHAR(36) NOT NULL, note TEXT NULL, user_un_id CHAR(36) NULL, created_at DATETIME NULL, KEY vf (visa_file_un_id));
CREATE TABLE visa_costs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, visa_file_un_id CHAR(36) NOT NULL, cost_type VARCHAR(40) NOT NULL, amount DECIMAL(15,2) NOT NULL, date DATE NOT NULL, party_un_id CHAR(36) NULL, account_un_id CHAR(36) NULL, transaction_un_id CHAR(36) NULL, note TEXT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY vf (visa_file_un_id));
CREATE TABLE visa_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, visa_file_un_id CHAR(36) NOT NULL, doc_type VARCHAR(40) NOT NULL, attachment_un_id CHAR(36) NULL, issue_date DATE NULL, expiry_date DATE NULL, status VARCHAR(12) DEFAULT 'pending', verified_by CHAR(36) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY vf (visa_file_un_id));
CREATE TABLE payment_schedules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, visa_file_un_id CHAR(36) NOT NULL, due_date DATE NOT NULL, amount DECIMAL(15,2) NOT NULL, paid_amount DECIMAL(15,2) DEFAULT 0, status VARCHAR(10) DEFAULT 'due', created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY vf (visa_file_un_id));
CREATE TABLE project_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, icon VARCHAR(40) NULL, unit_label VARCHAR(20) NULL, stages JSON NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, project_type_un_id CHAR(36) NULL, no VARCHAR(30) NULL, name VARCHAR(150) NOT NULL, location VARCHAR(150) NULL, start_date DATE NULL, end_date DATE NULL, status VARCHAR(20) DEFAULT 'running', budget DECIMAL(15,2) DEFAULT 0, output_unit VARCHAR(20) NULL, manager_un_id CHAR(36) NULL, meta JSON NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NULL, name VARCHAR(150) NOT NULL, category_un_id CHAR(36) NULL, unit VARCHAR(12) NULL, kind VARCHAR(10) DEFAULT 'input', created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE project_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, project_un_id CHAR(36) NOT NULL, kind VARCHAR(10) NOT NULL, date DATE NOT NULL, item_un_id CHAR(36) NULL, description VARCHAR(200) NULL, quantity DECIMAL(15,3) DEFAULT 0, unit VARCHAR(12) NULL, rate DECIMAL(15,2) DEFAULT 0, vat DECIMAL(15,2) DEFAULT 0, amount DECIMAL(15,2) DEFAULT 0, party_un_id CHAR(36) NULL, account_un_id CHAR(36) NULL, employee_un_id CHAR(36) NULL, transaction_un_id CHAR(36) NULL, note TEXT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY pj (project_un_id, kind));
CREATE TABLE project_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, project_un_id CHAR(36) NOT NULL, date DATE NOT NULL, title VARCHAR(150) NOT NULL, body TEXT NULL, data JSON NULL, created_by CHAR(36) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE employees (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, code VARCHAR(20) NULL, name VARCHAR(120) NOT NULL, phone VARCHAR(30) NULL, nid VARCHAR(40) NULL, photo VARCHAR(255) NULL, designation VARCHAR(80) NULL, department VARCHAR(80) NULL, employment_type VARCHAR(10) DEFAULT 'monthly', salary DECIMAL(15,2) DEFAULT 0, allowances JSON NULL, daily_rate DECIMAL(15,2) DEFAULT 0, join_date DATE NULL, status VARCHAR(20) DEFAULT 'active', bank_info VARCHAR(200) NULL, meta JSON NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_un_id CHAR(36) NOT NULL, date DATE NOT NULL, status CHAR(1) NOT NULL, note VARCHAR(200) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, UNIQUE KEY ed (employee_un_id, date));
CREATE TABLE advances (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, employee_un_id CHAR(36) NOT NULL, date DATE NOT NULL, amount DECIMAL(15,2) NOT NULL, installment DECIMAL(15,2) DEFAULT 0, repaid DECIMAL(15,2) DEFAULT 0, status VARCHAR(10) DEFAULT 'open', account_un_id CHAR(36) NULL, transaction_un_id CHAR(36) NULL, note TEXT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL);
CREATE TABLE payroll_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, business_un_id CHAR(36) NOT NULL, period CHAR(7) NOT NULL, status VARCHAR(10) DEFAULT 'draft', total DECIMAL(15,2) DEFAULT 0, approved_by CHAR(36) NULL, paid_at DATETIME NULL, account_un_id CHAR(36) NULL, transaction_un_id CHAR(36) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, UNIQUE KEY bp (business_un_id, period));
CREATE TABLE payroll_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, un_id CHAR(36) NOT NULL UNIQUE, run_un_id CHAR(36) NOT NULL, employee_un_id CHAR(36) NOT NULL, days_present DECIMAL(5,1) DEFAULT 0, days_total INT DEFAULT 0, basic DECIMAL(15,2) DEFAULT 0, allowances DECIMAL(15,2) DEFAULT 0, overtime DECIMAL(15,2) DEFAULT 0, bonus DECIMAL(15,2) DEFAULT 0, deductions DECIMAL(15,2) DEFAULT 0, advance_deduction DECIMAL(15,2) DEFAULT 0, net DECIMAL(15,2) DEFAULT 0, note VARCHAR(200) NULL, created_at DATETIME NULL, updated_at DATETIME NULL, deleted_at DATETIME NULL, KEY rn (run_un_id))
